    /* ═══ Global Reset & Foundations ═══ */
    * {
        box-sizing: border-box;
    }

    html {
        scroll-behavior: smooth;
    }

    /* Branded text selection */
    ::-moz-selection {
        background: rgba(126, 231, 255, 0.22);
        color: #f5fbff;
    }
    ::selection {
        background: rgba(126, 231, 255, 0.22);
        color: #f5fbff;
    }

    /* Accessible focus ring — visible only on keyboard nav */
    :focus-visible {
        outline: 2px solid rgba(126, 231, 255, 0.42);
        outline-offset: 2px;
    }

    /* Inputs handle their own focus styles */
    input:focus-visible,
    textarea:focus-visible,
    select:focus-visible {
        outline: none;
    }

    /* Typography Hierarchy */
    h1 {
        font-family: 'JetBrains Mono', monospace;
        font-size: 2rem;
        font-weight: 700;
        letter-spacing: 0.05em;
        text-transform: uppercase;
        color: #e8e4c8;
        margin: 0 0 1.5rem 0;
        line-height: 1.2;
    }

    h2 {
        font-family: 'JetBrains Mono', monospace;
        font-size: 1.5rem;
        font-weight: 700;
        letter-spacing: 0.05em;
        text-transform: uppercase;
        color: #ddd7b8;
        margin: 0 0 1rem 0;
        line-height: 1.3;
    }

    h3 {
        font-family: 'JetBrains Mono', monospace;
        font-size: 1.25rem;
        font-weight: 600;
        letter-spacing: 0.05em;
        text-transform: uppercase;
        color: #c9c39f;
        margin: 0 0 0.75rem 0;
        line-height: 1.4;
    }

    h4, h5, h6 {
        font-family: 'JetBrains Mono', monospace;
        font-weight: 600;
        letter-spacing: 0.05em;
        text-transform: uppercase;
        color: #bdb691;
        margin: 0 0 0.5rem 0;
    }

    p {
        font-family: 'JetBrains Mono', monospace;
		color: rgba(184, 198, 226, 0.72);
		color: var(--shell-text-soft);
        margin: 0 0 1rem 0;
        line-height: 1.6;
    }

    /* Professional Panels & Cards */
    .panel,
    .card,
    [class*="panel"] {
        background: linear-gradient(180deg, rgba(23, 31, 48, 0.95) 0%, rgba(10, 15, 25, 0.98) 100%);
        border: 1px solid rgba(120, 160, 220, 0.18);
        border: 1px solid var(--shell-border);
        border-radius: 24px;
        border-radius: var(--shell-radius-lg);
        box-shadow:
            0 20px 40px rgba(0, 0, 0, 0.3),
            0 0 0 1px rgba(126, 231, 255, 0.04),
            inset 0 1px 0 rgba(255, 255, 255, 0.05);
        color: rgba(233, 240, 255, 0.88);
        color: var(--shell-text);
        padding: 1.5rem;
        transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    }

    .panel:hover,
    .card:hover {
        box-shadow:
            0 24px 48px rgba(0, 0, 0, 0.38),
            0 0 0 1px rgba(126, 231, 255, 0.08),
            inset 0 1px 0 rgba(255, 255, 255, 0.06);
        border-color: rgba(126, 231, 255, 0.28);
        border-color: var(--shell-border-strong);
        transform: translateY(-1px);
    }

    /* Professional Input Styling */
    input,
    textarea,
    select {
        background: linear-gradient(180deg, rgba(8, 12, 20, 0.92) 0%, rgba(14, 19, 31, 0.96) 100%);
        border: 1px solid rgba(120, 160, 220, 0.18);
        border: 1px solid var(--shell-border);
        border-radius: 12px;
        border-radius: var(--shell-radius-sm);
        color: rgba(233, 240, 255, 0.88);
        color: var(--shell-text);
        font-family: 'JetBrains Mono', monospace;
        font-size: 0.875rem;
        padding: 0.75rem 1rem;
        transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
        box-shadow:
            inset 0 1px 0 rgba(255, 255, 255, 0.04),
            inset 0 -1px 0 rgba(255, 255, 255, 0.02),
            0 10px 20px rgba(0, 0, 0, 0.12);
    }

    input:focus,
    textarea:focus,
    select:focus {
        outline: none;
        border-color: rgba(126, 231, 255, 0.28);
        border-color: var(--shell-border-strong);
        box-shadow:
            0 0 0 3px rgba(126, 231, 255, 0.12),
            0 10px 24px rgba(0, 0, 0, 0.18),
            inset 0 1px 0 rgba(255, 255, 255, 0.05);
    }

    input::-moz-placeholder, textarea::-moz-placeholder {
		color: rgba(140, 160, 199, 0.52);
		color: var(--shell-muted);
    }

    input::placeholder,
    textarea::placeholder {
		color: rgba(140, 160, 199, 0.52);
		color: var(--shell-muted);
    }

    input[type='file'] {
		padding: 0.625rem;
		border-style: dashed;
		background: linear-gradient(180deg, rgba(10, 15, 25, 0.88) 0%, rgba(19, 27, 42, 0.92) 100%);
    }

    input[type='file']::file-selector-button {
		margin-right: 0.85rem;
		padding: 0.625rem 1rem;
		border: 1px solid rgba(120, 160, 220, 0.18);
		border: 1px solid var(--shell-border);
		border-radius: 999px;
		background: linear-gradient(135deg, rgba(126, 231, 255, 0.18) 0%, rgba(83, 183, 255, 0.18) 100%);
		color: rgba(233, 240, 255, 0.88);
		color: var(--shell-text);
		font: inherit;
		font-size: 0.75rem;
		font-weight: 700;
		letter-spacing: 0.08em;
		text-transform: uppercase;
		cursor: pointer;
    }

    input[type='file']::file-selector-button:hover {
		border-color: rgba(126, 231, 255, 0.28);
		border-color: var(--shell-border-strong);
		background: linear-gradient(135deg, rgba(126, 231, 255, 0.26) 0%, rgba(255, 212, 121, 0.18) 100%);
    }

    /* Professional Button Styling */
    button,
    a[class*="btn"],
    a.empty-action {
        position: relative;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.55rem;
        font-family: 'JetBrains Mono', monospace;
        font-size: 0.8125rem;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.05em;
		border: 1px solid rgba(120, 160, 220, 0.18);
		border: 1px solid var(--shell-border);
        border-radius: 18px;
        border-radius: var(--shell-radius-md);
		background: linear-gradient(180deg, rgba(24, 33, 50, 0.96) 0%, rgba(11, 15, 25, 0.98) 100%);
		color: rgba(233, 240, 255, 0.88);
		color: var(--shell-text);
        padding: 0.75rem 1.5rem;
        cursor: pointer;
        -webkit-text-decoration: none;
        -webkit-text-decoration: none;
        text-decoration: none;
        border-bottom: none;
        overflow: hidden;
        isolation: isolate;
        transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
        box-shadow:
			0 14px 26px rgba(0, 0, 0, 0.22),
			0 0 0 1px rgba(126, 231, 255, 0.04),
			inset 0 1px 0 rgba(255, 255, 255, 0.05);
    }

    button::before,
    a[class*="btn"]::before,
    a.empty-action::before {
        content: '';
        position: absolute;
        top: 1px;
        right: 1px;
        bottom: 1px;
        left: 1px;
        border-radius: calc(18px - 4px);
        border-radius: calc(var(--shell-radius-md) - 4px);
        background:
            linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent 38%),
            linear-gradient(90deg, rgba(126, 231, 255, 0.08), transparent 42%, rgba(255, 212, 121, 0.06));
        pointer-events: none;
    }

    button:hover:not(:disabled),
    a[class*="btn"]:hover,
    a.empty-action:hover {
        background: linear-gradient(180deg, rgba(34, 46, 70, 0.98) 0%, rgba(15, 21, 33, 1) 100%);
        border-color: rgba(126, 231, 255, 0.28);
        border-color: var(--shell-border-strong);
        box-shadow:
            0 18px 34px rgba(0, 0, 0, 0.3),
            0 0 0 1px rgba(126, 231, 255, 0.08),
            inset 0 1px 0 rgba(255, 255, 255, 0.06);
        transform: translateY(-1px);
    }

    button:active:not(:disabled) {
        transform: translateY(1px) scale(0.98);
        box-shadow:
            0 0px 1px rgba(0, 0, 0, 0.4),
            inset 0 2px 4px rgba(0, 0, 0, 0.15);
        transition-duration: 0.05s;
    }

    button:disabled {
        opacity: 0.35;
        cursor: not-allowed;
        filter: grayscale(0.3);
    }

    /* Danger Button */
    button.danger,
    button[class*="btn-danger"] {
        background: linear-gradient(135deg, #ff7585 0%, #ff5b71 48%, #db3d58 100%);
        color: #fff;
        border-color: rgba(255, 107, 120, 0.45);
    }

    button.danger:hover:not(:disabled),
    button[class*="btn-danger"]:hover:not(:disabled) {
        background: linear-gradient(135deg, #ff8a97 0%, #ff6074 48%, #e0445f 100%);
        box-shadow: 0 18px 32px rgba(255, 91, 113, 0.18);
    }

